    tex:(n)=>{ const t=typeof K.tex==='function'?K.tex(n):null; return t||ownTex(THREE,n); },
    lamp:(g,v,o)=>{ (g.userData.kitLamps=g.userData.kitLamps||[]).push({pos:v.clone(),color:o.color,tag:o.tag}); if(typeof K.lamp==='function') K.lamp(g,v,o); },
