    bark:   new THREE.MeshStandardMaterial({map:T('bark_col'),normalMap:T('bark_nrm'),roughness:1,metalness:0}),
    bone:   new THREE.MeshStandardMaterial({map:T('bone_col'),normalMap:T('bone_nrm'),roughness:.85,metalness:0}),
    metal:  new THREE.MeshStandardMaterial({map:T('metal_col'),normalMap:T('metal_nrm'),roughness:.5,metalness:.75}),
    mono:   new THREE.MeshStandardMaterial({color:0x0c0e18,roughness:.22,metalness:.25}),
    crystal:new THREE.MeshPhysicalMaterial({color:0x2b7fc4,emissive:0x1a7ae8,emissiveIntensity:1.5,roughness:.2,metalness:0,transparent:true,opacity:.9}),
    core:   new THREE.MeshBasicMaterial({color:0x8fd8ff,transparent:true,opacity:.35,toneMapped:false,depthWrite:false}),
