function fire(B,x,y,z,s=1){ for(let i=0;i<3;i++) B.cone(.2*s*(1-i*.22),.8*s*(1-i*.18),6,'glow',x+B.r(-.06,.06),y+i*.12*s,z+B.r(-.06,.06),{color:i<2?GLOW.flame:GLOW.flameCore,noShadow:true}); B.lamp(x,y+.9*s,z,'flame'); }
